const listRegistrations = `-- name: ListRegistrations :many
SELECT r.id, r.event_id, r.reference, r.contact_first_name, r.contact_last_name, r.contact_email, r.contact_phone, r.status, r.total_cents, r.currency, r.hold_expires_at, r.pay_later, r.checkout_key, r.oversold, r.emailed, r.created_at, r.confirmed_at, r.cancelled_at, e.title AS event_title,
    (SELECT count(*) FROM attendees a WHERE a.registration_id = r.id AND a.status = 'active')::int AS attendee_count,
    (SELECT COALESCE(sum(p.amount_cents), 0) FROM payments p WHERE p.registration_id = r.id AND p.status = 'paid')::bigint AS paid_cents
FROM registrations r
JOIN events e ON e.id = r.event_id
WHERE ($1::uuid IS NULL OR r.event_id = $1)
  AND ($2::text IS NULL OR r.status = $2)
  AND ($3::text IS NULL
       OR r.reference ILIKE '%' || $3 || '%'
       OR r.contact_email ILIKE '%' || $3 || '%'
       OR (r.contact_first_name || ' ' || r.contact_last_name) ILIKE '%' || $3 || '%')
ORDER BY r.created_at DESC, r.id DESC
LIMIT 500
`

type ListRegistrationsParams struct {
	EventID *string
	Status  *string
	Search  *string
}

type ListRegistrationsRow struct {
	ID               string
	EventID          string
	Reference        string
	ContactFirstName string
	ContactLastName  string
	ContactEmail     string
	ContactPhone     string
	Status           string
	TotalCents       int64
	Currency         string
	HoldExpiresAt    time.Time
	PayLater         bool
	CheckoutKey      string
	Oversold         bool
	Emailed          bool
	CreatedAt        time.Time
	ConfirmedAt      *time.Time
	CancelledAt      *time.Time
	EventTitle       string
	AttendeeCount    int
	PaidCents        int64
}

// The admin's list: newest first, optionally one event, one status, and a
// search over the reference and the person who registered. The attendee count
// and the amount paid come with each row, so the list needs no second query.
func (q *Queries) ListRegistrations(ctx context.Context, arg ListRegistrationsParams) ([]ListRegistrationsRow, error) {
	rows, err := q.db.Query(ctx, listRegistrations, arg.EventID, arg.Status, arg.Search)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListRegistrationsRow{}
	for rows.Next() {
		var i ListRegistrationsRow
		if err := rows.Scan(
			&i.ID,
			&i.EventID,
			&i.Reference,
			&i.ContactFirstName,
			&i.ContactLastName,
			&i.ContactEmail,
			&i.ContactPhone,
			&i.Status,
			&i.TotalCents,
			&i.Currency,
			&i.HoldExpiresAt,
			&i.PayLater,
			&i.CheckoutKey,
			&i.Oversold,
			&i.Emailed,
			&i.CreatedAt,
			&i.ConfirmedAt,
			&i.CancelledAt,
			&i.EventTitle,
			&i.AttendeeCount,
			&i.PaidCents,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockEvent = `-- name: LockEvent :one
SELECT id, slug, title, summary, description, venue, address, starts_at, ends_at, timezone, image_key, capacity, status, listed, registration_opens_at, registration_closes_at, pay_later, pay_later_instructions, created_at, updated_at FROM events WHERE id = $1 FOR UPDATE
`

// Checkouts for one event are serialised on its row: capacity is counted and
// spent under this lock, so two people cannot both take the last seat.
func (q *Queries) LockEvent(ctx context.Context, id string) (Event, error) {
	row := q.db.QueryRow(ctx, lockEvent, id)
	var i Event
	err := row.Scan(
		&i.ID,
		&i.Slug,
		&i.Title,
		&i.Summary,
		&i.Description,
		&i.Venue,
		&i.Address,
		&i.StartsAt,
		&i.EndsAt,
		&i.Timezone,
		&i.ImageKey,
		&i.Capacity,
		&i.Status,
		&i.Listed,
		&i.RegistrationOpensAt,
		&i.RegistrationClosesAt,
		&i.PayLater,
		&i.PayLaterInstructions,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

