const recordPaymentNotice = `-- name: RecordPaymentNotice :exec
UPDATE payments SET
    gateway_ref = COALESCE(gateway_ref, $1),
    gateway_status = $2,
    gateway_amount = $3,
    gateway_payload = $4,
    status = CASE WHEN status = 'paid' THEN status ELSE $5 END
WHERE id = $6
`

type RecordPaymentNoticeParams struct {
	GatewayRef     *string
	GatewayStatus  string
	GatewayAmount  string
	GatewayPayload string
	Status         string
	ID             string
}

// What a gateway said, kept whether or not it was "paid". A paid payment is
// never moved back: a late "pending" or "failed" notification after a success
// is the gateway's history, not ours.
func (q *Queries) RecordPaymentNotice(ctx context.Context, arg RecordPaymentNoticeParams) error {
	_, err := q.db.Exec(ctx, recordPaymentNotice,
		arg.GatewayRef,
		arg.GatewayStatus,
		arg.GatewayAmount,
		arg.GatewayPayload,
		arg.Status,
		arg.ID,
	)
	return err
}

